import newsData from "./generated/news.json";

// Lab news, generated by scripts/sync-sheets.mjs from the Google Sheet. The sync
// step already validates dates, normalizes them to ISO `YYYY-MM-DD` and assigns
// each item its URL slug, so this module only reads the data.
//
// The News page renders this whole list; the Home page pulls the latest few
// items via `getLatestNews()`.

export type NewsItem = {
  title: string;
  /** ISO date, `YYYY-MM-DD`. */
  date: string;
  /** Stable URL slug used by the detail route `/news/$slug`. */
  slug: string;
  img: string;
  /** Optional Korean body (markdown) shown on the news detail page. */
  contentKo?: string;
  /** Optional English body (markdown) shown on the news detail page. */
  contentEn?: string;
};

/** Shown when a news item has no image of its own. */
export const NEWS_IMG_FALLBACK = "/images/news/default-idl-lab-logo.png";

export const NEWS: NewsItem[] = (newsData as NewsItem[]).map((item) => ({
  ...item,
  img: item.img || NEWS_IMG_FALLBACK,
}));

/** Returns news sorted newest-first. */
export const getSortedNews = (): NewsItem[] =>
  [...NEWS].sort((a, b) => b.date.localeCompare(a.date));

/** Returns the `count` most recent news items, newest-first. */
export const getLatestNews = (count: number): NewsItem[] => getSortedNews().slice(0, count);

/** Finds a single news item by its slug. */
export const getNewsBySlug = (slug: string): NewsItem | undefined =>
  NEWS.find((item) => item.slug === slug);
